    const approvedCount = Number(kpis.collectedCount) || 0;
    out.collectedPrev = prevCollected;
    out.approvedPrev = prevCount;
    out.collectedDelta = prevCollected > 0 ? (collected - prevCollected) / prevCollected * 100 : null;
